syntax:
For a class with virtual functions:

// Class declaration
class ClassName {
public:
    virtual void functionName();
    // ... other members
};

// Compiler-generated internal structure
// Each object contains a hidden pointer to the vtable
// The vtable is an array of function pointers, one per virtual function

// During object creation, the compiler initializes the vptr (vtable pointer) to point to the class's vtable
// Function calls via virtual functions are dispatched by following the vptr to the vtable and invoking the function pointer

code_example:
class Base {
public:
    virtual void foo() { /* base implementation */ }
};
class Derived : public Base {
public:
    void foo() override { /* derived implementation */ }
};

int main() {
    Base* p = new Derived(); // Object of Derived, vptr points to Derived's vtable
    p->foo(); // Calls Derived::foo() via vtable dispatch
    delete p;
}
